        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        String inputString = scanner.next();
        inputString = inputString.toLowerCase();
        int maxLength = -1;
        int wordIndex = 0;
        int openParenCount = 0;
        int underscoreCount = 0;
