    int totalChars;
    std::cin >> totalChars;
    std::string inputString;
    std::cin >> inputString;
    // Convert to lowercase
    for (auto &c : inputString) c = tolower(c);
    int maxLength = -1;
    int wordIndex = 0;
    int openParenCount = 0;
    int underscoreCount = 0;
    for (int index = 0; index < totalChars; index++) {
        char ch = inputString[index];
        if (ch == '(') {
            openParenCount++;
            underscoreCount = 0;
        } else if (ch == ')') {
            if (openParenCount == 1 && underscoreCount != 0) wordIndex++;
            openParenCount--;
            underscoreCount = 0;
        } else if (ch == '_') {
            if (openParenCount == 1 && underscoreCount != 0) wordIndex++;
            underscoreCount = 0;
        } else {
            underscoreCount++;
        }
        if (openParenCount == 0) {
            maxLength = std::max(underscoreCount, maxLength);
        }
    }
    std::cout << maxLength << " " << wordIndex << std::endl;
    return 0;
